 "content": "def transform(grid):
    # The special symbols on the horizontal line rise into vertical columns.
    # Their heights encode their order in the symbol sequence: 2 rises higher
    # than 8; the original horizontal line is preserved.
    out = [row[:] for row in grid]
    base = next((r for r, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if base is None:
        return out
    # extend each special marker upward, with 2 one cell taller than 8
    for c, v in enumerate(grid[base]):
        if v in (2, 8):
            height = 4 if v == 2 else 3
            for r in range(max(0, base-height), base):
                out[r][c] = 1
            if base-height >= 0:
                out[base-height][c] = v
    return out
